<template><div class="table-wrap"><table><thead><tr><th>Code</th><th>Nom de la catégorie</th><th>Description de la catégorie</th><th>Réparateurs attachés</th><th>Statut</th><th>Actions</th></tr></thead><tbody><tr v-for="category in categories" :key="category.id"><td>#{{ String(category.id).padStart(2,'0') }}</td><td class="name"><strong>{{ category.name }}</strong></td><td class="description">{{ category.description }}</td><td><strong>{{ category.repairers }} réparateur{{ category.repairers > 1 ? 's' : '' }}</strong></td><td><span :class="['badge',category.active?'active':'inactive']">● {{ category.active ? 'Active' : 'Inactive' }}</span></td><td class="actions"><button @click="$emit('edit',category)">Modifier</button><button class="delete" @click="$emit('delete',category)">Supprimer</button></td></tr><tr v-if="!categories.length"><td class="empty" colspan="6">Aucune catégorie ne correspond à votre recherche.</td></tr></tbody></table></div></template>
<script setup>defineProps({categories:{type:Array,required:true}});defineEmits(['edit','delete'])</script>
<style scoped>.table-wrap{overflow:auto;border:1px solid #e1ecfa;border-radius:9px}table{border-collapse:collapse;width:100%;min-width:930px;background:#fff}th{text-align:left;text-transform:uppercase;font-size:11px;color:#244879;background:#e6efff;padding:13px 14px}td{padding:17px 14px;border-bottom:1px solid #e5eef9;color:#113f85;font-size:13px}tbody tr:nth-child(even){background:#f0faf8}tbody tr:nth-child(odd){background:#fff}tr:last-child td{border-bottom:0}.name{min-width:210px;color:#174b50}.description{max-width:310px;color:#5273a6;line-height:1.4}.badge{display:inline-block;padding:7px 12px;border-radius:18px;font-size:12px}.active{background:#dff8ef;color:#009f72}.inactive{background:#e9f1fb;color:#5878ad}.actions{display:flex;align-items:center;gap:9px;white-space:nowrap}.actions button{box-sizing:border-box;display:inline-flex;align-items:center;justify-content:center;width:112px;height:46px;padding:9px 12px;background:#fff;border:1px solid #8cbdff;border-radius:8px;color:#087f70;font-size:12px;font-weight:700}.actions button.delete{box-sizing:border-box;display:inline-flex;align-items:center;justify-content:center;width:112px;height:46px;padding:9px 12px;background:#fff;border:1px solid #ff94a7;border-radius:8px;color:#ff3554;font-size:12px;font-weight:700}.empty{text-align:center;padding:35px;color:#6381b5}</style>
